def f(v, fmt="%.4g"):
    if v is None: return "not measured"
    if isinstance(v, bool): return "yes" if v else "no"
    if isinstance(v, (int, float)):
        try: return fmt % v
        except Exception: return str(v)
    return str(v)
def shell_of_max(r):
    """shell edges of the holdout rho_u^max (std family) from the start file; sphere radius of the single-sphere maximum from the ledger."""
    try:
        S = torch.load(os.path.join(ROOT, r["zfile"]), map_location="cpu", weights_only=False)
        sd = S.get("spec_diag_holdout") or {}; ru = sd.get("rho_u") or []; ed = (sd.get("shells") or {}).get("edges") or []
        k = max(range(len(ru)), key=lambda i: (ru[i] if ru[i] is not None else -1)) if ru else None
        s1 = f"rho_u^max std in shell [{ed[k][0]:.3g}, {ed[k][1]:.3g})" if k is not None and ed else "not measured"
        rn = sd.get("rho_nl") or []
        kn = max(range(len(rn)), key=lambda i: (rn[i] if rn[i] is not None else -1)) if rn else None
        s2 = f"rho_nl^max in shell [{ed[kn][0]:.3g}, {ed[kn][1]:.3g})" if kn is not None and ed else "not measured"
        gram = ""
        gr = sd.get("gram") or {}
        if gr and ed:
            core = [i for i in range(len(ed)) if ed[i][1] <= 1.0 + 1e-12 and (gr.get("gamma") or [None] * len(ed))[i] is not None]
            gram = "; ".join(f"[{ed[i][0]:.3g},{ed[i][1]:.3g}) b/a {gr['b_rms_N'][i] / max(gr['a_rms_L'][i], 1e-300):.2f} gamma {gr['gamma'][i]:+.2f}" for i in core) or "not measured"
        return s1, s2, gram
    except Exception as e:
        return "not measured", "not measured", "not measured"
def row_for(label, jobs, mech, fa):
    done = [(j, by_job[j][-1]) for j in jobs if j in by_job]
    if not done:
        return None if not a.mark_incomplete else f"| {label} | not measured | incomplete at II.4 (no finished level) | " + " | ".join(["not measured"] * 11) + f" | {mech} ({fa}) |"
    j0, r0 = done[0]; jl, rl = done[-1]
    cfg = None
    for d in ("done", "running", "pending", "failed", "cancelled", "hold", "hold_lowprio"):
        pth = os.path.join(ROOT, "queue", d, jl + ".json")
        if os.path.exists(pth):
            cfg = json.load(open(pth)).get("config", {}); break
    cfg = cfg or {}
    ch = cfg.get("channels") or {}
    klass = f"{rl.get('m_parity')} basis, L {rl.get('L')} Nk {rl.get('Nk')}, channels {ch.get('NkB', 0)}/{ch.get('NkD', 0)}/{ch.get('NkE', 0)} deg {ch.get('LB', '-')}/{ch.get('LD', '-')}/{ch.get('LE', '-')}, c_l {rl.get('c_l')}, omega {rl.get('omega')} (omega/c_l {rl.get('omega') / rl.get('c_l'):.3f}), {rl.get('formulation')} {rl.get('nl_denominator')}" + (f", closure {cfg.get('closure_lambda')}" if cfg.get("closure_lambda") else "") + "".join(f", {k} {cfg[k]}" for k in ("both_weight", "radial_lambda_w", "balance_lambda", "nu", "core_pin", "nonaxi_pin", "boost_e_core", "perturb_m", "fsw") if cfg.get(k) is not None)
